/**
 * Canonical athlete data layer for the Startlete demo.
 *
 * Reads the fictional seed dataset in `data/athletes.json` (generated by
 * `data/seed.mjs`) and adapts each record to the UI `Athlete` view shape the
 * screen components already consume, extended with a `regionCode` so the
 * interactive Philippines map can scope athletes by region.
 *
 * The actual transform lives in `data/athlete-adapter.mjs` so it can be shared,
 * dependency-free, with the Node test suite. This module adds the TypeScript
 * view type for use inside the Next.js app.
 *
 * All data here is entirely fictional. See `data/README.md` for the fake-data
 * safety rules. No real athlete identities, PII, verification proofs, or
 * payment information may be introduced.
 */
import seed from "@/data/athletes.json";
import { adaptAthletes } from "@/data/athlete-adapter.mjs";

/** UI view shape used by the Startlete screens. */
export interface Athlete {
  id: number;
  name: string;
  sport: string;
  location: string;
  /** Canonical Philippine region code (e.g. "NCR", "Region XI"). */
  regionCode: string;
  /** Full administrative region name, for labels. */
  region: string;
  /**
   * Photo gallery. The FIRST photo is the profile picture shown on the card,
   * map, leaderboard, and navbar circle. Empty when the athlete has no photos
   * (the UI then falls back to a placeholder).
   */
  photos: AthletePhoto[];
  /**
   * Backward-compatible single image: the profile picture src (first photo) or
   * the placeholder. Kept so existing render sites work unchanged.
   */
  image: string;
  raised: number;
  goal: number;
  supporters: number;
  verified: boolean;
  featured?: boolean;
  bio: string;
  /** Full achievement list; at most one is flagged `isProudest`. */
  achievements: Achievement[];
  /** Backward-compatible proudest achievement title (or first), for old copy. */
  achievement: string;
}

/** A single gallery photo. `src` is a data URL (demo) or seed image URL. */
export interface AthletePhoto {
  id: string;
  /** Safe, generated file name (never a client-supplied name). */
  name: string;
  src: string;
  /** Alt text, e.g. "Photo of <name>". */
  alt: string;
}

/** A self-reported achievement. Per-achievement verification is not modeled. */
export interface Achievement {
  id: string;
  title: string;
  /** Competition / meet / event name (optional). */
  event: string;
  /** "YYYY" or "YYYY-MM-DD" (optional). */
  date: string;
  /** Short description (optional). */
  description: string;
  /** At most one achievement per athlete is the proudest. */
  isProudest: boolean;
}

const seedAthletes = (seed as { athletes: Record<string, unknown>[] }).athletes;

/** The full set of fictional athletes, adapted to the UI view shape. */
export const athletes: Athlete[] = adaptAthletes(seedAthletes) as Athlete[];

export default athletes;
